import{_ as c,C as l,o as a,c as h,a2 as d,b as i,w as t,a as o,E as n,a3 as s,j as p}from"./chunks/framework.Dg5fKO7V.js";const A=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"Architecture-Overview.md","filePath":"Architecture-Overview.md","lastUpdated":1788563284000}'),u={name:"Architecture-Overview.md"};function m(b,e,f,y,v,w){const r=l("Mermaid");return a(),h("div",null,[e[2]||(e[2]=d('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>AniSphere is a <a href="https://tauri.app" target="_blank" rel="noreferrer">Tauri 2</a> desktop application. Rust owns durable data, remote services, media transport, downloads and operating-system integration. SolidJS owns presentation and transient interaction state. Typed Tauri commands are the boundary between them.</p><h2 id="dependency-direction" tabindex="-1">Dependency direction <a class="header-anchor" href="#dependency-direction" aria-label="Permalink to &quot;Dependency direction&quot;">​</a></h2><p>Dependencies point toward stable policy and never back toward composition:</p>',4)),(a(),i(s,null,{default:t(()=>[n(r,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20LR%0A%20%20shell%5B%22app%20shell%22%5D%20--%3E%20features%0A%20%20features%20--%3E%20shared%5B%22shared%20capabilities%22%5D%0A%20%20shared%20--%3E%20config%0A%20%20features%20--%3E%20assets%0A%20%20shared%20--%3E%20assets%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=p("p",null,"Across the process boundary the same rule holds, and every arrow crosses it once:",-1)),(a(),i(s,null,{default:t(()=>[n(r,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20LR%0A%20%20io%5B%22frontend%20io%22%5D%20--%3E%20ipc%5B%22shared%2Fipc%22%5D%0A%20%20ipc%20--%3E%20commands%5B%22Tauri%20commands%22%5D%0A%20%20commands%20--%3E%20backend%5B%22backend%20subsystems%22%5D%0A%20%20backend%20--%3E%20store%5B(%22SQLite%22)%5D%0A%20%20backend%20--%3E%20net%5B%22network%22%5D%0A%20%20backend%20--%3E%20os%5B%22operating%20system%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p>ESLint and architecture tests enforce the important edges. In particular, UI cannot invoke the backend, feature models cannot import IO or UI, shared code cannot import a feature, and config has no imports at all.</p><h2 id="frontend-map" tabindex="-1">Frontend map <a class="header-anchor" href="#frontend-map" aria-label="Permalink to &quot;Frontend map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Directory</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>src/app/</code></td><td>Process boot, route composition, application-wide event wiring and the shell</td></tr><tr><td><code>src/features/</code></td><td>Vertical product capabilities such as anime, player, library and settings</td></tr><tr><td><code>src/shared/</code></td><td>Stable capabilities deliberately used by more than one feature</td></tr><tr><td><code>src/config/</code></td><td>Named tuning values: timings, limits and layout measurements, with their rationale</td></tr><tr><td><code>src/assets/</code></td><td>Static data shipped with the application, including world-country geometry</td></tr></tbody></table><p>Every feature uses the same four-folder vocabulary:</p><table tabindex="0"><thead><tr><th>Feature folder</th><th>Owns</th></tr></thead><tbody><tr><td><code>ui/</code></td><td>Solid components and rendering-only helpers</td></tr><tr><td><code>io/</code></td><td>Resources, persistence, platform calls and lifecycle orchestration</td></tr><tr><td><code>model/</code></td><td>Pure decisions, transformations, types and state machines</td></tr><tr><td><code>tests/</code></td><td>Feature behaviour and interaction tests</td></tr></tbody></table><p>This is a vertical-slice architecture, not a repository-wide collection of controllers and components. A contributor looking for player behaviour starts in <code>features/player</code> and can see its rendering, effects and decisions together.</p><p>Shared code is not divided into generic <code>io</code> and <code>model</code> buckets. Its top-level folders name the capability they offer: <code>api</code>, <code>media</code>, <code>network</code>, <code>preferences</code>, <code>track</code>, <code>i18n</code>, <code>ui</code> and the other packages documented in <a href="./Architecture-Frontend">Frontend Architecture</a>. This makes an import explain why the dependency exists.</p><h2 id="backend-map" tabindex="-1">Backend map <a class="header-anchor" href="#backend-map" aria-label="Permalink to &quot;Backend map&quot;">​</a></h2><p>Under <code>src-tauri/src/</code>:</p><table tabindex="0"><thead><tr><th>Directory</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>app/</code></td><td>Starts Tauri, registers commands and owns native-window behaviour</td></tr><tr><td><code>catalog/</code></td><td>Imports the title catalogue, and fetches remote metadata for what a screen is showing</td></tr><tr><td><code>commands/</code></td><td>Thin, serializable IPC boundary grouped by subject</td></tr><tr><td><code>database/</code></td><td>SQLite schema, migrations, persisted models and query families</td></tr><tr><td><code>providers/</code></td><td>One streaming-site adapter per folder behind a common contract</td></tr><tr><td><code>provider_pool/</code></td><td>Matching, health, failover and caching across providers</td></tr><tr><td><code>server/</code></td><td>Loopback image, local-file and media proxy</td></tr><tr><td><code>downloads/</code></td><td>Queue, transfer, FFmpeg assembly and offline snapshots</td></tr><tr><td><code>integrations/</code></td><td>AniList, Kitsu, Discord presence, AniSkip and imports</td></tr><tr><td><code>platform/</code></td><td>Operating-system-specific behaviour behind one surface</td></tr></tbody></table><p>Every Rust file starts with inner module documentation (<code>//!</code>). Crate-public items use <code>///</code> so their contract is readable without opening the implementation.</p><h2 id="who-owns-which-fact" tabindex="-1">Who owns which fact <a class="header-anchor" href="#who-owns-which-fact" aria-label="Permalink to &quot;Who owns which fact&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fact</th><th>Owner</th><th>Not the owner</th></tr></thead><tbody><tr><td>Which anime exist, their titles and ids</td><td>manami catalogue</td><td>AniList, providers</td></tr><tr><td>How many episodes a season has, when it airs</td><td>AniList</td><td>providers</td></tr><tr><td>Which episodes can actually be played</td><td>selected provider</td><td>AniList</td></tr><tr><td>Per-episode titles and thumbnails</td><td>Kitsu, with AniList fallback</td><td>providers</td></tr></tbody></table><p>An AniList episode count is not proof that a provider can play that episode. The UI may show a metadata count and a playable episode list that disagree. Collapsing the two would invent a link that is not there.</p><h2 id="compatibility-contracts" tabindex="-1">Compatibility contracts <a class="header-anchor" href="#compatibility-contracts" aria-label="Permalink to &quot;Compatibility contracts&quot;">​</a></h2><p>The following require an explicit migration or product decision, not a structural refactor:</p><ul><li>Tauri command names and payload shapes</li><li>Event names and payloads</li><li>Persisted data, settings keys and avatar seeds</li><li>Provider ids and provider order</li><li>Routes and deep links</li><li>Cleanup behaviour on profile switch and shutdown</li></ul><p>Database migrations are additive. Columns are added before the indexes that depend on them, and user data is never recreated merely because a schema version changed.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="./Architecture-Frontend">Frontend Architecture</a></li><li><a href="./Architecture-Backend">Backend Architecture</a></li><li><a href="./Provider-System">Provider System</a></li><li><a href="./Playback-And-Proxy">Playback and Proxy</a></li><li><a href="./Downloads-And-Offline">Downloads and Offline</a></li><li><a href="./Data-Privacy-And-Security">Data, Privacy and Security</a></li></ul>',20))])}const k=c(u,[["render",m]]);export{A as __pageData,k as default};
